class CorbaPeerFrame {
public:
    using PayloadVariant = ::cpp11::variant<TelemetryRecord, EventRecord, AlarmRecord, ControlCommand, Acknowledgement>;

    uint8 record_id() const { return record_id_; }
    void set_record_id(uint8 v) { record_id_ = v; }
    uint16 length() const { return length_; }
    void set_length(uint16 v) { length_ = v; }

    const PayloadVariant& payload() const { return payload_; }
    PayloadVariant& payload() { return payload_; }

    static CorbaPeerFrame wrap(const TelemetryRecord& msg) {
        CorbaPeerFrame frame;
        frame.record_id_ = TelemetryRecord::ID_VALUE;
        frame.payload_ = msg;
        return frame;
    }

    static CorbaPeerFrame wrap(const EventRecord& msg) {
        CorbaPeerFrame frame;
        frame.record_id_ = EventRecord::ID_VALUE;
        frame.payload_ = msg;
        return frame;
    }

    static CorbaPeerFrame wrap(const AlarmRecord& msg) {
        CorbaPeerFrame frame;
        frame.record_id_ = AlarmRecord::ID_VALUE;
        frame.payload_ = msg;
        return frame;
    }

    static CorbaPeerFrame wrap(const ControlCommand& msg) {
        CorbaPeerFrame frame;
        frame.record_id_ = ControlCommand::ID_VALUE;
        frame.payload_ = msg;
        return frame;
    }

    static CorbaPeerFrame wrap(const Acknowledgement& msg) {
        CorbaPeerFrame frame;
        frame.record_id_ = Acknowledgement::ID_VALUE;
        frame.payload_ = msg;
        return frame;
    }

    ::bgen11::VoidResult encode(::bgen11::io::BitWriter& w) const {
        auto frame_start_pos_ = w.size_bytes();
        w.write_u8(static_cast<uint8_t>(record_id_));
        auto length_byte_pos_ = w.size_bytes();
        w.write_u16(static_cast<uint16_t>(0), ::bgen11::io::Endian_Big);
        BGEN11_TRY(::bgen11::detail::variant_encode(payload_, w));
        if (!w.patch_u16(length_byte_pos_, static_cast<uint16_t>(w.size_bytes() - frame_start_pos_), ::bgen11::io::Endian_Big))
            return ::cpp11::make_unexpected(::bgen11::Error(::bgen11::ErrorCode_InvalidArgument, "failed to patch frame length"));
        return {};
    }

    static ::bgen11::Result<CorbaPeerFrame> decode(::bgen11::io::BitReader& r) {
        CorbaPeerFrame result;
        auto record_id_val_ = r.read_u8();
        if (!record_id_val_) return ::cpp11::make_unexpected(record_id_val_.error());
        result.record_id_ = *record_id_val_;
        auto length_val_ = r.read_u16(::bgen11::io::Endian_Big);
        if (!length_val_) return ::cpp11::make_unexpected(length_val_.error());
        result.length_ = *length_val_;
        switch (static_cast<uint8>(result.record_id_)) {
            case 1: {
                auto payload_val_ = TelemetryRecord::decode(r);
                if (!payload_val_) return ::cpp11::make_unexpected(payload_val_.error());
                payload_val_->record_id_ = result.record_id_;
                payload_val_->length_ = result.length_;
                result.payload_ = std::move(*payload_val_);
                break;
            }
            case 10: {
                auto payload_val_ = ControlCommand::decode(r);
                if (!payload_val_) return ::cpp11::make_unexpected(payload_val_.error());
                payload_val_->record_id_ = result.record_id_;
                payload_val_->length_ = result.length_;
                result.payload_ = std::move(*payload_val_);
                break;
            }
            case 11: {
                auto payload_val_ = Acknowledgement::decode(r);
                if (!payload_val_) return ::cpp11::make_unexpected(payload_val_.error());
                payload_val_->record_id_ = result.record_id_;
                payload_val_->length_ = result.length_;
                result.payload_ = std::move(*payload_val_);
                break;
            }
            case 2: {
                auto payload_val_ = EventRecord::decode(r);
                if (!payload_val_) return ::cpp11::make_unexpected(payload_val_.error());
                payload_val_->record_id_ = result.record_id_;
                payload_val_->length_ = result.length_;
                result.payload_ = std::move(*payload_val_);
                break;
            }
            case 3: {
                auto payload_val_ = AlarmRecord::decode(r);
                if (!payload_val_) return ::cpp11::make_unexpected(payload_val_.error());
                payload_val_->record_id_ = result.record_id_;
                payload_val_->length_ = result.length_;
                result.payload_ = std::move(*payload_val_);
                break;
            }
            default:
                return ::cpp11::make_unexpected(::bgen11::Error(::bgen11::ErrorCode_UnknownDiscriminator,
                    "unknown frame message id: " + std::to_string(static_cast<int>(result.record_id_))));
        }
        return result;
    }

    ::bgen11::Result<std::vector<uint8_t>> encode_bytes() const {
        ::bgen11::io::BitWriter w;
        BGEN11_TRY(encode(w));
        return w.finish();
    }

    static ::bgen11::Result<CorbaPeerFrame> decode_bytes(::cpp11::span<const uint8_t> data) {
        ::bgen11::io::BitReader r(data);
        return decode(r);
    }

    std::string to_string() const {
        std::ostringstream oss;
        oss << "CorbaPeerFrame{"
            << "record-id=" << +(record_id_)
            << ", length=" << +(length_)
            << ", payload=" << ::bgen11::detail::variant_to_string(payload_)
            << "}";
        return oss.str();
    }

private:
    uint8 record_id_{};
    uint16 length_{};
    PayloadVariant payload_;
};

